/*
  LOAD STATE FROM N8N STATIC DATA
  Static data persists between workflow runs in n8n's database.
  No external file needed — works on any platform.
*/
const sd = $getWorkflowStaticData('global');

// First-run seed: mark historical bookings so we don't re-alert on them
if (!sd.processed) {
  sd.processed = {};
  const historical = [
    'CR-00304','CR-00305','CR-00306','CR-00311','CR-00313','CR-00314',
    'CR-00315','CR-00316','CR-00318','CR-00319','CR-00321','CR-00323',
    'CR-00324','CR-00325','CR-00326','CR-00327','CR-00328','CR-00329',
    'CR-00330','CR-00331','CR-00332','US-315544'
  ];
  for (const id of historical) {
    sd.processed[id] = {
      bookingId: id,
      trigger: 'PRE_EXISTING',
      emailSent: new Date().toISOString(),
      classification: 'Historical',
      score: 0,
      lastUpdated: new Date().toISOString()
    };
  }
}

// Compute time windows
const now = new Date();
return [{
  json: {
    nowISO:  now.toISOString(),
    minus35: new Date(now.getTime() -  35 * 60 * 1000).toISOString(),
    minus2h: new Date(now.getTime() -   2 * 60 * 60 * 1000).toISOString(),
    plus72h: new Date(now.getTime() +  72 * 60 * 60 * 1000).toISOString(),
    state:   JSON.parse(JSON.stringify(sd.processed))
  }
}];

/*
  PARSE, FILTER, AND DEDUP ZOHO BOOKINGS EVENTS
  - Deduplicates merged calendar results by event ID
  - Filters to Zoho Bookings events only
  - Parses all fields from the structured description
  - Checks Meet link presence
  - Performs deduplication against saved state
  - Returns all Zoho events (with trigger=null for already-processed ones)
*/
const state = $('Load State').first().json.state;

function parseField(desc, field) {
  const rx = new RegExp(field + '\\s*:\\s*([^\\n\\r]+)', 'i');
  const m = (desc || '').match(rx);
  return m ? m[1].trim() : '';
}

// Deduplicate by event ID across both calendar query results
const seen = new Set();
const allEvents = [];
for (const item of $input.all()) {
  const ev = item.json;
  if (!ev || !ev.id || seen.has(ev.id)) continue;
  seen.add(ev.id);
  allEvents.push(ev);
}

// Keep only Zoho Bookings events
const zohoEvents = allEvents.filter(ev => {
  const d = ev.description || '';
  return d.includes('Booking ID') || d.includes('Customer Info') ||
         d.includes('Service Info') || d.includes('Service Name');
});

if (zohoEvents.length === 0) return [];

const results = [];
for (const ev of zohoEvents) {
  const desc = ev.description || '';
  const bookingId  = parseField(desc, 'Booking ID');
  const email      = parseField(desc, 'Email');
  const startTime  = ev.start?.dateTime || ev.start?.date || '';
  const key        = bookingId || (ev.id + '_' + email + '_' + startTime);

  // Detect existing Meet link
  const hangoutLink = ev.hangoutLink || null;
  const confPoints  = (ev.conferenceData?.entryPoints || []);
  const confMeet    = confPoints.find(e => (e.uri || '').includes('meet.google.com'));
  const locMeet     = (ev.location || '').includes('meet.google.com');
  const hasMeet     = !!(hangoutLink || confMeet || locMeet);
  const meetLink    = hangoutLink || confMeet?.uri || null;

  // Deduplication check
  const existing = state[key];
  let trigger = null;
  if (!existing) {
    trigger = 'NEW';
  } else {
    const lastTs    = new Date(existing.lastUpdated || existing.emailSent || 0).getTime();
    const updatedTs = new Date(ev.updated || 0).getTime();
    if ((updatedTs - lastTs) > 5 * 60 * 1000) trigger = 'UPDATED';
  }

  results.push({ json: {
    eventId:       ev.id,
    key,
    bookingId,
    trigger,
    hasMeet,
    meetLink,
    meetLinkAdded: false,
    name:         parseField(desc, 'Name'),
    email,
    phone:        parseField(desc, 'Contact Number'),
    company:      parseField(desc, 'Company Name'),
    website:      parseField(desc, 'Website'),
    serviceName:  parseField(desc, 'Service Name'),
    subject:      parseField(desc, 'Subject'),
    startTime,
    updatedAt:    ev.updated || '',
    processedAt:  new Date().toISOString()
  }});
}

return results;

/*
  Extract the new Meet link from the Calendar API response
  and merge it back with the original booking data.
  $('Needs Meet Link?').item.json gives us the paired input item.
*/
const apiResponse = $input.first().json;
const booking    = $('Needs Meet Link?').item.json;

const meetLink =
  apiResponse.hangoutLink ||
  (apiResponse.conferenceData?.entryPoints || [])
    .find(e => e.entryPointType === 'video')?.uri ||
  null;

return [{ json: { ...booking, meetLink, meetLinkAdded: !!meetLink, hasMeet: true } }];

/*
  Parse Claude API response.
  Claude returns: { content: [{ type: 'text', text: '{ JSON here }' }] }
  Strip any accidental markdown code fences before parsing.
*/
const apiResp  = $input.first().json;
const booking  = $('New or Updated?').item.json;

let analysis = {};
try {
  let raw = apiResp.content?.[0]?.text || '{}';
  // Strip markdown fences if Claude wrapped the JSON
  raw = raw.replace(/^```(?:json)?\n?/i, '').replace(/\n?```$/i, '').trim();
  analysis = JSON.parse(raw);
} catch (e) {
  console.error('Claude parse error:', e.message);
  analysis = {
    classification:  'Unknown',
    score:           5,
    executiveSummary: 'Booking received. Claude parsing failed — review manually.',
    emailSubject:    `New Booking: ${booking.name} | ${booking.company} | Score: ?/10 | Unknown`,
    emailHTML:       `<html><body style="font-family:Arial,sans-serif;padding:20px">
      <h2 style="color:#1a1a2e">New Booking Alert</h2>
      <p><strong>Name:</strong> ${booking.name}</p>
      <p><strong>Company:</strong> ${booking.company}</p>
      <p><strong>Email:</strong> ${booking.email}</p>
      <p><strong>Service:</strong> ${booking.serviceName}</p>
      <p><strong>Booking ID:</strong> ${booking.bookingId}</p>
      <p><strong>Meeting:</strong> ${booking.startTime}</p>
      <p><em>Intelligence enrichment unavailable — Claude API parsing error. Review manually.</em></p>
    </body></html>`
  };
}

return [{ json: { ...booking, ...analysis } }];

/*
  UPDATE STATE IN N8N STATIC DATA
  We write only the single new key — existing keys are preserved
  because we hold a reference to the same sd.processed object.
*/
const sd = $getWorkflowStaticData('global');
if (!sd.processed) sd.processed = {};

const item = $input.first().json;
const key  = item.key;

sd.processed[key] = {
  eventId:        item.eventId,
  bookingId:      item.bookingId,
  name:           item.name,
  email:          item.email,
  company:        item.company,
  lastUpdated:    item.updatedAt || new Date().toISOString(),
  emailSent:      new Date().toISOString(),
  classification: item.classification || 'Unknown',
  score:          item.score || 5,
  trigger:        item.trigger,
  meetLink:       item.meetLink || null,
  meetLinkAdded:  item.meetLinkAdded || false
};

console.log('[ZohoMonitor] State updated — key:', key, '| classification:', sd.processed[key].classification);

return [{ json: {
  success:        true,
  key,
  name:           item.name,
  classification: sd.processed[key].classification,
  score:          sd.processed[key].score,
  emailSent:      sd.processed[key].emailSent
}}];
